                    b.HasKey("Id");

                    b.HasIndex("ExamSessionId");

                    b.ToTable("Passages");

                    b.HasData(
                        new
                        {
                            Id = 1,
                            Content = "Над 80% от младите хора прекарват поне час на ден в платформите за видеосподеляне. Според проучвания клиповете са сред най-гледаните формати, като се предпочитат видеа с продължителност до три минути заради непретенциозното им съдържание и възможността да се гледат „на бегом“. Благодарение на такива видеа младежите се информират, забавляват и вдъхновяват, докато са у дома или в движение. Тези кратки, но същевременно динамични 3 формати са изключително привлекателни – те мигновено предоставят развлечение, като понякога дори изненадват със задълбочеността си. Разнообразието на това, което младите хора гледат, е голямо – комични ситуации, танцови предизвикателства, музикални клипове... Кратките видеа предлагат вихрушка от цветове, звуци, емоции и идеи. В тази динамична среда ключова роля играят инфлуенсърите – харизматичните лидери на дигиталната сцена. Те не просто създават съдържание, а с активната си дейност в платформите за споделяне на видеа изграждат връзка с аудиторията си, вдъхновяват, провокират промяна на нагласите и популяризират нови тенденции. „Ще ти покажа как да успееш!“, „Нека заедно опитаме нещо ново!“ – това не са просто фрази, а мостове към сърцата на милиони млади хора. Несъмнено потреблението на видеосъдържание има и своята тъмна страна. Тъй като клиповете предлагат бързо удовлетворяване на любопитството и лесен достъп до безкрайно разнообразие от съдържание, прекомерното им гледане крие и опасности. Постоянното потапяне в дигиталното пространство създава усещане за свързаност със света и илюзия за динамично взаимодействие с него, като в същото време младите хора започват да пренебрегват физическата активност и директния контакт на живо. Според изследвания прекалено дългото време, прекарано пред екрана, води до понижаване на качеството на съня, до проблеми със зрението и дори до депресивни състояния. Освен това неограниченото гледане на клипове може да създаде зависимост, която в повечето случаи трудно се преодолява. Макар да са наясно с последиците от гледането на видеа, 90% от младите хора не искат да се откъснат от тази дейност, сочи изследване. Този избор не е случаен – за много от младите хора това е начин на живот и те не се нуждаят от „спасяване“, макар често по-възрастните да смятат обратното.",
                            ExamSessionId = 1,
                            Number = 1
                        },
                        new
                        {
                            Id = 2,
                            ExamSessionId = 1,
                            ImagePath = "/images/texts/text2026.png",
                            Number = 2
                        },
                        new
                        {
                            Id = 3,
                            Content = "Спортните занимания са важен фактор за постигане на добро физическо и психическо здраве. Според данните на Световната здравна организация при хората, които спортуват поне 150 минути седмично, има значително по-нисък риск от хронични заболявания и преждевременна смърт. Въпреки това заниманията със спорт имат и своите предизвикателства. Много специалисти предупреждават, че неправилната техника на изпълнение на упражненията, 3 прекомерното натоварване и омаловажаването на възстановителните периоди могат да доведат до сериозни травми. Скорошно изследване сочи, че около 30% от редовно спортуващите получават травми, които са резултат от липсата на загряване преди тренировка. Според експертите по спортна медицина съревнованието с другите спортуващи в залата често подтиква хората да надценяват възможностите си, което увеличава риска от дълготрайни увреждания. Съществуват и някои погрешни схващания около спортуването. Широко разпространено например е мнението, че тичането може да се практикува от всички. Ако човек обаче е с тегло дори и малко над нормата, рискът от травми е много по-голям. При бягане ставите на краката трябва да издържат на натоварване, което се равнява на утроеното собствено тегло. Друго разпространено схващане е, че разходката не е спорт. Данни от изследване обаче свидетелстват, че четири кратки разходки на ден са по-полезни от продължителен джогинг както за кръвообрaщението и работата на сърцето, така и за намаляването на високото кръвно налягане. Доказано е също така, че ако се изминават пеша кратки отсечки от по един километър, проблемите със съня намаляват наполовина. Танцуването пък се оказва, че е едно от най-ефективните и същевременно найполезните за гърба спортни занимания. Гръбначните мускули се стабилизират, а тялото изгаря за час танцуване около 600 килокалории. Редовните занимания с танци намаляват със 76% риска от деменция, сочи изследване. Народните танци например не само укрепват здравето – те съхраняват и културната идентичност чрез връзката с фолклора и обичаите. Някои експерти смятат обаче, че спортуването е само една част от здравословния начин на живот. Според повечето диетолози правилното хранене и качественият сън са не по-малко важни. Физическата активност може да подобри здравето, но без балансиран хранителен режим и без достатъчно почивка усилията може да бъдат напразни.",
                            ExamSessionId = 2,
                            Number = 1
                        },
                        new
                        {
                            Id = 4,
                            ExamSessionId = 2,
                            ImagePath = "/images/texts/text2025.png",
                            Number = 2
                        });
                });

